export function textFor(s,en,bangla){return s.language==='bn'?(bangla||bn[en]||en):en;}
export function localizedProduct(s,p,key){return s.language==='bn'?(p[key+'Bn']||p[key]||''):(p[key]||'');}
// Translate known interface text only; never translate input values or HTML markup.
export function localizeMarkup(html,s){if(s.language!=='bn')return html;return html.replace(/>([^<>]+)</g,(whole,text)=>{const key=text.trim();let value=bn[key];if(!value&&/^Colour:/.test(key))value=key.replace('Colour:','রং:');if(!value&&/^Size:/.test(key))value=key.replace('Size:','সাইজ:');if(!value&&/^Quantity /.test(key))value=key.replace('Quantity ','পরিমাণ ');if(!value&&/^Bag · /.test(key))value=key.replace('Bag','ব্যাগ');if(!value&&/^\d+ available$/.test(key))value=key.replace('available','স্টকে আছে');if(!value&&/^Hello, /.test(key))value=key.replace('Hello, ','স্বাগতম, ');if(!value&&/^\d+ pieces/.test(key))value=key.replace('pieces in this preview collection','টি নমুনা পণ্য এই কালেকশনে').replace('pieces, chosen by you.','টি পণ্য আপনার পছন্দে।');return value?'>'+text.replace(key,E(value))+'<':whole;}).replace(/(placeholder|aria-label)="([^"]+)"/g,(all,name,value)=>bn[value]?`${name}="${E(bn[value])}"`:all);}
export function detectChatLanguage(text,previous='en'){if(/[\u0980-\u09ff]/u.test(text))return 'bn';if(/\b(ami|amar|amr|apni|tumi|kemon|kivabe|ki|koto|chai|cai|chay|lagbe|hobe|ache|ase|nai|naii|dekhau|dekhao|dekhan|dekhte|kinte|kinsi|kinbo|juta|juto|den|dao|diben|korbo|koren|korte|bhalo|valo|banglish|taka|dam|dorkar|shathe|sathe|kotha)\b/i.test(text))return 'bn-Latn';if(/\b(hello|please|show|buy|want|need|what|how|where|can|the|my|is|are|thanks|english|status|delivery|shipping|refund|return|payment|shoes|bags|wallet|hi)\b/i.test(text))return 'en';return previous;}
